INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-towaie-1', 'sent-ex-towaie-1', 'en', 'Spring though it is, the mornings are cold.', 'authored'),
  ('st-ex-towaie-2', 'sent-ex-towaie-2', 'en', 'Convenient though it is, the price is high.', 'authored'),
  ('st-ex-towaie-3', 'sent-ex-towaie-3', 'en', 'Child though he is, he has responsibilities.', 'authored'),
  ('st-ex-towaie-4', 'sent-ex-towaie-4', 'en', 'Busy though I am, I need a day off.', 'authored'),
  ('st-ex-karatoitte-1', 'sent-ex-karatoitte-1', 'en', 'Just because it is cheap does not mean you have to buy the lot.', 'authored'),
  ('st-ex-karatoitte-2', 'sent-ex-karatoitte-2', 'en', 'Being a student does not mean you can write every kanji.', 'authored'),
  ('st-ex-karatoitte-3', 'sent-ex-karatoitte-3', 'en', 'The match will not be called off just because it is raining.', 'authored'),
  ('st-ex-karatoitte-4', 'sent-ex-karatoitte-4', 'en', 'Expensive does not necessarily mean well made.', 'authored'),
  ('st-ex-towakagiranai-1', 'sent-ex-towakagiranai-1', 'en', 'The expensive one is not necessarily the good one.', 'authored'),
  ('st-ex-towakagiranai-2', 'sent-ex-towakagiranai-2', 'en', 'A famous shop does not always serve good food.', 'authored'),
  ('st-ex-towakagiranai-3', 'sent-ex-towakagiranai-3', 'en', 'Working hard does not always mean succeeding.', 'authored'),
  ('st-ex-towakagiranai-4', 'sent-ex-towakagiranai-4', 'en', 'The doctor is not necessarily right.', 'authored'),
  ('st-ex-nisuginai-1', 'sent-ex-nisuginai-1', 'en', 'That is nothing but an excuse.', 'authored'),
  ('st-ex-nisuginai-2', 'sent-ex-nisuginai-2', 'en', 'He is no more than a child.', 'authored'),
  ('st-ex-nisuginai-3', 'sent-ex-nisuginai-3', 'en', 'It is only my imagination.', 'authored'),
  ('st-ex-nisuginai-4', 'sent-ex-nisuginai-4', 'en', 'This is only the beginning.', 'authored'),
  ('st-ex-hokanaranai-1', 'sent-ex-hokanaranai-1', 'en', 'Success is nothing other than the result of effort.', 'authored'),
  ('st-ex-hokanaranai-2', 'sent-ex-hokanaranai-2', 'en', 'This is thanks to him and nothing else.', 'authored'),
  ('st-ex-hokanaranai-3', 'sent-ex-hokanaranai-3', 'en', 'Failure is nothing but experience.', 'authored'),
  ('st-ex-hokanaranai-4', 'sent-ex-hokanaranai-4', 'en', 'That sound is nothing but the wind.', 'authored'),
  ('st-ex-nashini-1', 'sent-ex-nashini-1', 'en', 'Please do not enter without permission.', 'authored'),
  ('st-ex-nashini-2', 'sent-ex-nashini-2', 'en', 'He took the day off without letting anyone know.', 'authored'),
  ('st-ex-nashini-3', 'sent-ex-nashini-3', 'en', 'You can use it without booking.', 'authored'),
  ('st-ex-nashini-4', 'sent-ex-nashini-4', 'en', 'They started without any explanation.', 'authored'),
  ('st-ex-nukini-1', 'sent-ex-nukini-1', 'en', 'Let us talk with the joking left out.', 'authored'),
  ('st-ex-nukini-2', 'sent-ex-nukini-2', 'en', 'Without his help I could not have done it.', 'authored'),
  ('st-ex-nukini-3', 'sent-ex-nukini-3', 'en', 'I went out without any breakfast.', 'authored'),
  ('st-ex-nukini-4', 'sent-ex-nukini-4', 'en', 'Without an explanation I cannot follow it.', 'authored'),
  ('st-ex-kkiri-1', 'sent-ex-kkiri-1', 'en', 'I have met him just the once.', 'authored'),
  ('st-ex-kkiri-2', 'sent-ex-kkiri-2', 'en', 'My older brother went out and has not been back since.', 'authored'),
  ('st-ex-kkiri-3', 'sent-ex-kkiri-3', 'en', 'We talked, just the two of us.', 'authored'),
  ('st-ex-kkiri-4', 'sent-ex-kkiri-4', 'en', 'I borrowed that book and never gave it back.', 'authored'),
  ('st-ex-shidai-1', 'sent-ex-shidai-1', 'en', 'I will get in touch as soon as I arrive.', 'authored'),
  ('st-ex-shidai-2', 'sent-ex-shidai-2', 'en', 'I will go home the moment the meeting ends.', 'authored'),
  ('st-ex-shidai-3', 'sent-ex-shidai-3', 'en', 'I will tell you as soon as I know.', 'authored'),
  ('st-ex-shidai-4', 'sent-ex-shidai-4', 'en', 'We will start as soon as everything is ready.', 'authored'),
  ('st-ex-kainaka-1', 'sent-ex-kainaka-1', 'en', 'I have not decided whether to go or not.', 'authored'),
  ('st-ex-kainaka-2', 'sent-ex-kainaka-2', 'en', 'I will check whether it is right or not.', 'authored'),
  ('st-ex-kainaka-3', 'sent-ex-kainaka-3', 'en', 'Whether it succeeds or not depends on the effort.', 'authored'),
  ('st-ex-kainaka-4', 'sent-ex-kainaka-4', 'en', 'Please tell me whether you are taking part or not.', 'authored')
